(52405,0,0,'%s goes into a frenzy!',16,0,100,0,0,0,''),
(52409,0,0,'Come forth, my servants! Defend your master!',14,0,100,0,0,24513,'Ragnaros adds 1'),
(52409,0,1,'Minions of fire! Purge the outsiders!',14,0,100,0,0,24514,'Ragnaros adds 2'),
(52409,0,2,'Denizens of flame, come to me!',14,0,100,0,0,24515,'Ragnaros adds 3'),
(52409,0,3,'Arise, servants of fire, consume their flesh!',14,0,100,0,0,24516,'Ragnaros adds 4'),
(52409,1,0,'Mortal Insects! You dare trespass into MY domain?  Your arrogance will be purged in living flame.',14,0,100,0,0,24517,'Ragnaros intro'),
(52409,2,0,'No, noooo- This was to be my hour of triumph...',14,0,100,0,0,24518,'Ragnaros death heroic');
INSERT INTO `tmp_548_creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(52409,3,0,'Too soon! ... You have come too soon...',14,0,100,0,0,24519,'Ragnaros death normal'),
(52409,4,0,'You will be crushed!',14,0,100,0,0,24520,'Ragnaros hammer drop 1'),
(52409,4,1,'Die!',14,0,100,0,0,24521,'Ragnaros hammer drop 2'),
(52409,4,2,'Your judgement has come!',14,0,100,0,0,24522,'Ragnaros hammer drop 3'),
(52409,5,0,'Enough! I will finish this.',14,0,100,0,0,24523,'Ragnaros hummer pickup 1'),
(52409,5,1,'Fall to your knees, mortals!  This ends now.',14,0,100,0,0,24524,'Ragnaros hummer pickup 2'),
(52409,5,2,'Sulfuras will be your end.',14,0,100,0,0,24525,'Ragnaros hummer pickup 3'),
(52409,6,0,'When I finish this, your pathetic mortal world will burn with my vengeance!',14,0,100,0,0,24526,'Ragnaros heroic 03'),
(52409,7,0,'Arrggh, outsiders - this is not your realm!',14,0,100,0,0,24527,'Ragnaros heroic 02'),
(52409,8,0,'Too soon...',14,0,100,0,0,24528,'Ragnaros heroic 01'),
(52409,9,0,'This is MY realm!',14,0,100,0,0,24529,'Ragnaros kill 03'),
(52409,9,1,'Pathetic.',14,0,100,0,0,24530,'Ragnaros kill 02'),
(52409,9,2,'Die, insect!',14,0,100,0,0,24531,'Ragnaros kill 01'),
(52409,10,0,'By fire be purged!',14,0,25,0,0,24532,'Ragnaros purge'),
(52409,11,0,'Deathwing has prepared me to face the vessel of Tarecgosa, your fools journey ends here!',14,0,100,0,0,25162,'Ragnaros event'),
(52409,12,0,'Begone from my realm, insects.',14,0,100,0,0,24533,'Ragnaros aggro 1'),
(52409,12,1,'I will see you all burn.',14,0,100,0,0,24534,'Ragnaros aggro 2'),
(52409,12,2,'Be consumed by flame!',14,0,100,0,0,24535,'Ragnaros aggro 3'),
(52409,12,3,'The realm of fire will consume you!',14,0,100,0,0,24536,'Ragnaros aggro 4'),
(52440,0,0,'%s goes into a frenzy!',16,0,100,0,0,0,''),
(52558,0,0,'Hah? Hruumph? Soft little fleshy-things? Here? Nuisances, nuisances!',14,0,100,0,0,24537,'Rhyolith aggro'),
(52558,1,0,'Oww now hey.',14,0,100,0,0,24540,'Rhyolith chunk 01'),
(52558,1,1,'Graaahh!',14,0,100,0,0,24541,'Rhyolith chunk 02'),
(52558,1,2,'Augh - smooshy little pests, look what you\'ve done!',14,0,100,0,0,24542,'Rhyolith chunk 03'),
(52558,1,3,'Uurrghh now you... you infuriate me!',14,0,100,0,0,24543,'Rhyolith chunk 04'),
(52558,1,4,'Oh you little beasts...',14,0,100,0,0,24544,'Rhyolith chunk 05'),
(52558,2,0,'Broken. Mnngghhh... broken...',14,0,100,0,0,24545,'Rhyolith death'),
(52558,3,0,'Finished.',14,0,100,0,0,24546,'Rhyolith kill 01'),
(52558,3,1,'So soft!',14,0,100,0,0,24547,'Rhyolith kill 02'),
(52558,3,2,'Squeak, little pest.',14,0,100,0,0,24548,'Rhyolith kill 03'),
(52558,4,0,'Buuurrnnnn!',14,0,100,0,0,24550,'Rhyolith lava 01'),
(52558,4,1,'Succumb to living flame.',14,0,100,0,0,24551,'Rhyolith lava 02'),
(52558,4,2,'My inner fire can never die.',14,0,100,0,0,24552,'Rhyolith lava 03'),
(52558,4,3,'Consume...',14,0,100,0,0,24553,'Rhyolith lava 04'),
(52558,4,4,'Flesh... burns!',14,0,100,0,0,24554,'Rhyolith lava 05'),
(52558,5,0,'Stomp now.',14,0,100,0,0,24556,'Rhyolith stomp 1'),
(52558,5,1,'I\'ll crush you underfoot!',14,0,100,0,0,24557,'Rhyolith stomp 02'),
(52558,6,0,'Eons I have slept undisturbed... Now this... Creatures of flesh, now you will BURN!',14,0,100,0,0,24558,'Rhyolith transform'),
(52571,0,0,'The master\'s power takes on many forms...',14,0,100,0,0,24483,'Majordomo Staghelm - SAY_TRANSFORM_1'),
(52571,1,0,'Behold the rage of the Firelands!',14,0,100,0,0,24485,'Majordomo Staghelm - SAY_TRANSFORM_2'),
(52571,2,0,'Blaze of Glory!',14,0,100,0,0,24472,'Majordomo Staghelm - SAY_HUMANOID_1'),
(52571,3,0,'Nothing but ash!',14,0,100,0,0,24478,'Majordomo Staghelm - SAY_HUMANOID_2'),
(52571,4,0,'My studies... had only just begun...',14,0,100,0,0,24471,'Majordomo Staghelm - SAY_DEATH'),
(52571,5,0,'So much power!',14,0,100,0,0,24480,'Majordomo Staghelm - SAY_BERSERK'),
(52571,6,0,'Burn.',14,0,100,0,0,24477,'Majordomo Staghelm - SAY_KILL_1'),
(52571,6,1,'Soon ALL of Azeroth will burn!',14,0,100,0,0,24479,'Majordomo Staghelm - SAY_KILL_2'),
(52571,6,2,'You stood in the fire!',14,0,100,0,0,24481,'Majordomo Staghelm - SAY_KILL_3'),
(52606,0,0,'%s becomes enraged!',16,0,100,0,0,0,''),
(53494,0,0,'You are forbidden from my master\'s domain, mortals.',14,0,0,0,0,24441,'Baleroc aggro'),
(53494,1,0,'Mortal filth... the master\'s keep is forbidden....',14,0,0,0,0,24444,'Baleroc death'),
(53494,2,0,'Fool mortals. Hurl yourselves into your own demise!',14,0,0,0,0,24446,'Baleroc event 02'),
(53494,3,0,'By the Firelord\'s command, you, too, shall perish!',14,0,0,0,0,24447,'Baleroc event03'),
(53494,4,0,'You have been judged.',14,0,0,0,0,24449,'Baleroc kill 02'),
(53494,4,1,'Behold your weakness.',14,0,0,0,0,24451,'Baleroc kill 04'),
(53494,4,2,'None shall pass!',14,0,0,0,0,24452,'Baleroc kill 05'),
(53494,5,0,'Your flesh is forfeit to the fires of this realm.',14,0,0,0,0,24450,'Baleroc kill 03'),
(53494,6,0,'Burn beneath my molten fury!',14,0,0,0,0,24459,'Baleroc quest 03'),
(53619,0,0,'Kneel before the burning flame!',14,0,100,0,0,24810,''),
(53691,0,0,'A-hah! The interlopers! Kill them. EAT THEM!',14,0,0,0,0,24565,'Shannox aggro'),
(53691,1,0,'Ohh... the pain.  Lord of Fire, it hurts....',14,0,0,0,0,24568,'Shannox death'),
(53691,2,0,'Fetch your supper!',14,0,0,0,0,24569,'Shannox dog attack 05'),
(53691,3,0,'Go for the throat!',14,0,0,0,0,24573,'Shannox dog attack 01'),
(53691,4,0,'Riplimb! No... no! Oh, you terrible little beasts! How could you?!',14,0,0,0,0,24574,'Shannox dogdeath 01'),
(53691,5,0,'Oh, you murderers! Why? Why would you kill such a noble animal?',14,0,0,0,0,24575,'Shannox dogdeath 02'),
(53691,6,0,'Now you burn!',14,0,0,0,0,24576,'Shannox fireattack 01'),
(53691,6,1,'Twist in flames, interlopers!',14,0,0,0,0,24577,'Shannox fireattack 02'),
(53691,7,0,'Dog food!',14,0,0,0,0,24578,'Shannox kill 04'),
(53691,7,1,'Now you stay dead!',14,0,0,0,0,24579,'Shannox kill 03'),
(53691,7,2,'The Firelord will be most pleased.',14,0,0,0,0,24580,'Shannox kill 02'),
(53691,8,0,'Yes, I smell them too, Riplimb. Outsiders encroach on the Firelord\'s private grounds. Find their trail. Find them for me, that I may dispense punishment!',14,0,0,0,0,24584,'Shannox spawn'),
(54015,0,0,'What have we here - visitors to our kingdom in the Firelands?',14,0,100,1,0,24466,''),
(54015,1,0,'You mortals may remember Alysra, who spirited me to freedom in Mount Hyjal. She, too has been reborn. Born of flame!',14,0,100,1,0,24467,''),
(54015,2,0,'I wish I could watch her reduce your pitiful band to cinders, but I am needed elsewhere. Farewell!',14,0,100,1,0,24468,''),
(54123,0,0,'Another band of Deathwing\'s converts? I\'ll be sure your death is especially painful.',14,0,100,0,0,25966,'Sylvanas aggro'),
(54123,1,0,'This... isn\'t how it\'s supposed to... end.',14,0,100,0,0,25967,'Sylvanas death'),
(54123,2,0,'And so ends your story.',14,0,100,0,0,25968,'Sylvanas reset'),
(54123,3,0,'Cry havoc!',14,0,100,0,0,25969,'Sylvanas kill'),
(54123,4,0,'Watch, heathens, as death surrounds you!',14,0,100,0,0,25970,'Sylvanas spell 01'),
(54431,0,0,'What dark horrors have you wrought in this place? By my ancestors\' honor, I shall take you to task!',14,0,100,0,0,25909,'Baine aggro'),
(54431,1,0,'Where... is this place? What... have I done? Forgive me, my father...',14,0,100,0,0,25910,'Baine death'),
(54431,2,0,'You! Are you the ones responsible for what has happened here...?',14,0,100,0,0,25911,'Baine intro'),
(54431,3,0,'This is the price you pay!',14,0,100,0,0,25912,'Baine kill 01'),
(54431,3,1,'A just punishment!',14,0,100,0,0,25913,'Baine kill 02'),
(54431,3,2,'Suffer for your arrogance!',14,0,100,0,0,25914,'Baine kill 03'),
(54431,4,0,'There will be no escape!',14,0,100,0,0,25915,'Baine spell 01'),
(54431,4,1,'My wrath knows no bounds!',14,0,100,0,0,25916,'Baine spell 02'),
(54432,0,0,'So be it.',14,0,100,0,0,25927,'Murozond aggro'),
(54432,1,0,'You know not what you have done. Aman\'Thul... What I... have... seen...',14,0,100,0,0,25928,'Murozond death'),
(54432,2,0,'The powers of the Hourglass do nothing to me!',14,0,100,0,0,25929,'Murozond event 01'),
(54432,3,0,'To repeat the same action and expect different results is madness.',14,0,100,0,0,25930,'Murozond event 02'),
(54432,4,0,'Another chance will make no difference. You will fail.',14,0,100,0,0,25931,'Murozond event 03'),
(54432,5,0,'Again...? Is this your plot, your scheme?',14,0,100,0,0,25932,'Murozond event 04'),
(54432,6,0,'The Hourglass\' power is exhausted. No more games, mortals. Relent, or perish.',14,0,100,0,0,25933,'Murozond event 05'),
(54432,7,0,'The "End Time," I once called this place. I had not seen, by then; I did not know. You hope to... what? Stop me, here? Change the fate I worked so tirelessly to weave?',14,0,100,0,0,25934,'Murozond intro 01'),
(54432,8,0,'You crawl unwitting, like a blind, writhing worm, towards endless madness and despair. I have witnessed the true End Time. This? This is a blessing you simply cannot comprehend.',14,0,100,0,0,25935,'Murozond intro 02'),
(54432,9,0,'Your time has come.',14,0,100,0,0,25936,'Murozond kill 01'),
(54432,9,1,'The sand has run out.',14,0,100,0,0,25937,'Murozond kill 02'),
(54432,9,2,'Time ends.',14,0,100,0,0,25938,'Murozond kill 03'),
(54445,0,0,'You asked for it.',14,0,100,0,0,25917,'Jaina aggro 01'),
(54445,0,1,'I hate resorting to violence.',14,0,100,0,0,25918,'Jaina aggro 02'),
(54445,1,0,'I understand, now. Farewell, and good luck.',12,0,100,0,0,25919,'Jaina death'),
(54445,2,0,'I don\'t know who you are, but I\'ll defend this shrine with my life. Leave, now, before we come to blows.',12,0,100,0,0,25920,'Jaina intro'),
(54445,3,0,'You forced my hand.',14,0,100,0,0,25921,'Jaina kill 01'),
(54445,3,1,'I didn\'t want to do that.',14,0,100,0,0,25922,'Jaina kill 02'),
(54445,3,2,'I wish you\'d surrendered.',14,0,100,0,0,25923,'Jaina kill 03'),
(54445,4,0,'Perhaps this will cool your heads...',14,0,100,0,0,25924,'Jaina spell 01'),
(54445,4,1,'A little ice ought to quench the fire in your hearts...',14,0,100,0,0,25925,'Jaina spell 02'),
(54445,4,2,'Why won\'t you give up?!',14,0,100,0,0,25926,'Jaina spell 03'),
