(54544,0,0,'Let the peaceful light of Elune soothe your souls in this dark time.',12,0,100,0,0,25972,'Tyrande '),
(54544,1,0,'Moon goddess, your light dims!  I am lost without your guidance!',14,0,100,0,0,25973,'Tyrande 80%'),
