(59200,4,0,'DIE, NECROMANCER!',14,0,100,0,0,29466,'LILIAN_TALK_5'),
(59200,5,0,'Leave me...to die...alone...please...',14,0,100,0,0,29467,'LILIAN_TALK_6'),
