(68323,13,0,'We also welcome everybody\'s favorite frosty feathered friend: Dippy!',14,0,100,22,0,0,''),
(68323,14,0,'Also entering the arena: Kirrawk, wind-wielding arakkoa of the Terokkar Forest!',14,0,100,22,0,0,''),
