(69475,5,0,'Zandalar...',12,0,100,0,0,35423,''),
(69481,0,0,'Elsia is waiting for you, champion.',12,0,100,0,0,35664,''),
(69481,1,0,'Rangers! Secure the forge. Smash the gate, so it cannot be closed!',14,0,100,0,0,35938,''),
(69481,2,0,'Incredible work. I knew the Shado-Pan would make excellent allies.',12,0,100,0,0,35666,''),
(69481,3,0,'Regardless, we have delivered a terrible blow to the Thunder King today. Horde metalsmiths can begin studying mogu fabrication techniques immediately.',12,0,100,0,0,35667,''),
