(70602,3,0,'BUT STAY AWAY FROM THE  BIG VILLAGE! There\'s dozens o\' mad ice trolls in there! Oh, that Zandalari priest has \'em whipped up into a great frenzy.',12,0,100,5,0,0,''),
(70605,0,0,'Newt, get that door open.',12,0,100,0,0,0,''),
(70605,1,0,'Grit, Ticker and Volt, you three back her up.',12,0,100,0,0,0,''),
(70605,2,0,'Recruit $p, you\'re with me.',12,0,100,0,0,0,''),
(70605,3,0,'We\'ve tracked the recent disappearances in Durotar to this abandoned section of Ragefire.',12,0,100,0,0,0,''),
(70605,4,0,'It\'s our job to find out who\'s behind these abductions and put a stop to them.',12,0,100,0,0,0,''),
(70605,5,0,'Stay close.',12,0,100,0,0,0,''),
(70605,6,0,'Newt, we need this door open now.',12,0,100,0,0,0,''),
(70605,7,0,'Move! Move! Move!',14,0,100,0,0,0,''),
(70605,8,0,'What the...',14,0,100,0,0,0,''),
