(70605,22,0,'Everyone out before more of them show up!',14,0,100,0,0,0,''),
(70606,0,0,'Yes, sir!',12,0,100,0,0,0,''),
(70606,1,0,'I\'m setting the last charge now, sir!',12,0,100,0,0,0,''),
