(71865,8,0,'|TInterface\\Icons\\ability_garrosh_whirling_corruption.blp:20|t%s begins to cast |cFFFF0000|Hspell:144985|h[Whirling Corruption]|h|r!',41,0,100,0,0,0,''),
(71865,9,0,'|TInterface\\Icons\\ability_garrosh_empowered_whirling_corruption.blp:20|t%s begins to cast |cFFFF0000|Hspell:144985|h[Empowered Whirling Corruption]|h|r!',41,0,100,0,0,0,''),
(71865,10,0,'The power to crush your world, and everything on it!',14,0,100,0,0,38077,''),
(71865,11,0,'The True Horde WILL come to pass.  I have SEEN it.  IT HAS SHOWN ME. I HAVE SEEN MOUNTAINS OF SKULLS AND RIVERS OF BLOOD.  AND I WILL...HAVE...MY...WORLD!',14,0,100,0,0,38056,''),
(71865,12,0,'Ha! Do you remember nothing of Honor? Of glory on the battlefield?  You who would parlay with the humans, who allowed warlocks to practice their dark magics right under our feet.  You are weak.',14,0,100,0,0,38059,''),
(71865,13,0,'We are the Orcish Horde, the True Horde.  We die, bloody and thrashing on the field of battle, like true orcs SHOULD.',14,0,100,0,0,38060,''),
(71865,14,0,'You are an Orc no longer, and speak for none but yourself. You betrayed our people to forge your fragile alliances, and I will take great pleasure in tearing them apart.',14,0,100,0,0,38061,''),
(71865,15,0,'Fool. My Dark Shaman have twisted and tortured the elements for miles around. They cannot hear you now. Once again you prove too weak and powerless to do anything.',14,0,100,0,0,38062,''),
(71865,16,0,'So, you wish to face off against a real Orc Warchief.  So be it.',14,0,100,0,0,38063,''),
(71865,17,0,'You think you have WON?  You are BLIND.  I WILL FORCE YOUR EYES OPEN.',14,0,100,0,0,38057,''),
(71865,18,0,'BEHOLD, MY GLORIOUS DESTINY!',14,0,100,0,0,38058,''),
(71865,19,0,'|TInterface\\Icons\\ability_warlock_eradication.blp:20|t%s casts |cFFFF0000|Hspell:147209|h[Malice]|h|r on |cFFFF0000$n|r!',41,0,100,0,0,0,''),
(71865,20,0,'THERE IS NO PLACE FOR YOU IN MY WORLD.',14,0,100,0,0,38049,''),
(71865,21,0,'|TInterface\\Icons\\ability_garrosh_siege_engine.blp:20|t The Fleet Captain detected a cluster! Firing |cFFFF0000|Hspell:147047|h[Unstable Iron Star]|h|r!',41,0,100,0,0,0,''),
(71865,22,0,'|TInterface\\Icons\\ability_vehicle_demolisherflamecatapult.blp:20|tThe Horde Fleet begins their |cFFFF0000|Hspell:147088|h[Bombardment]|h|r!',41,0,100,0,0,0,''),
(71865,23,0,'I WILL DESTROY EVERYTHING YOU HAVE EVER LOVED.',14,0,100,0,0,38050,''),
(71889,0,0,'Activating GB-11010 "Armageddon"-class defense systems. Hey, does anybody know if we\'re zoned for this?',14,0,100,0,0,38482,''),
(71889,1,0,'"Armageddon"-class defense systems fully on-line. Here comes the explosions!',14,0,100,0,0,38484,''),
(71889,2,0,'Module 1\'s all prepared for system reset.',14,0,100,0,0,38474,''),
(71889,3,0,'Module 2\'s all prepared for system reset.',14,0,100,0,0,38476,''),
(71889,4,0,'Security system deactivated.  Welcome back Siegecrafter Blackfuse.',14,0,100,0,0,38478,''),
(71889,5,0,'Hey, we recording?  Yeah?  Okay.  Goblin-Titan control module starting up, please stand back.',14,0,100,0,0,38479,''),
(71889,6,0,'Checking out the datas, hold on a second will ya.',14,0,100,0,0,38480,''),
(71889,7,0,'Oh, now you did it, that was really really really not the correct input code.',14,0,100,0,0,38481,''),
(71965,0,0,'Halt!',14,0,100,0,0,38883,''),
(71965,1,0,'No further corruption will enter the heart chamber!',14,0,100,0,0,38884,''),
(71965,2,0,'You wish to purge the corruption?',14,0,100,0,0,38885,''),
(71965,3,0,'Should you pass this door, at this time, you would fail!  You, all of you, are corrupted with the insiduous plague known as Pride.',14,0,100,0,0,38886,''),
(71965,4,0,'You stand tall and proud atop your accomplishments, and this will be your downfall.',14,0,100,0,0,0,''),
(71965,5,0,'Should you wish to defeat the corruption, you will first need to purify the corruption within yourselves.',14,0,100,0,0,0,''),
(71965,6,0,'Speak to me again when you are prepared to face your inner demons.',14,0,100,0,0,38887,''),
(71965,7,0,'Very well, I will create a field to keep your corruption quarantined.',14,0,100,0,0,38888,''),
(71965,8,0,'Prove yourselves worthy and I will let you pass.',14,0,100,0,0,38889,''),
(71965,9,0,'The light cleanses; but it is not gentle.  Gird yourselves and be purified!',14,0,100,0,0,38880,''),
(71965,10,0,'You have been judged, and proven yourselves worthy. But be warned, what lies beyond will try your souls to their utmost.  When you are fully prepared, you may enter the chamber.',14,0,100,0,0,38882,''),
(71965,11,0,'The corruption is amplifying.  The fragments must be purged before it becomes too great.',14,0,100,0,0,38903,''),
(71965,12,0,'It did not matter. It comes.  Steel your hearts and prepare your souls.',14,0,100,0,0,38904,''),
(71965,13,0,'The light will not suffer your taint.',14,0,100,0,0,38881,''),
(72145,0,0,'I will NOT burn like the rest! Face the demons you fear, traitors!',14,0,100,0,0,0,''),
(72191,0,0,'Our enemies have finally arrived!  Demolishers, fire at will!',14,0,100,0,0,38287,''),
(72192,0,0,'Hrnngg... thank you...',12,0,100,0,0,38276,''),
(72192,1,0,'I may be bruised and beaten, but the hatred boils inside me.',12,0,100,396,0,38277,''),
(72192,2,0,'Many times have I fallen at the hands of an Orc, and many times have I risen again.',12,0,100,396,0,38278,''),
(72192,3,0,'But never again.',12,0,100,274,0,38279,''),
(72192,4,0,'For every orc that struck me, I will cleave a thousand of their skulls!',12,0,100,5,0,38280,''),
(72192,5,0,'This ends here!',14,0,100,15,0,38281,''),
(72192,6,0,'I, Gamon, will save us!',14,0,100,71,0,38282,''),
(72192,7,0,'Taste my axe!',14,0,100,0,0,38271,''),
(72192,8,0,'Pay for your crimes!',14,0,100,0,0,38272,''),
(72192,9,0,'I am a storm of pain!',14,0,100,0,0,38283,''),
(72192,10,0,'You are an honorable Orc, Nazgrim. I regret what I must do.',12,0,100,0,0,38274,''),
(72192,11,0,'You fought with honor. Gamon will ensure that your legacy lives on. For the Horde, my friend.',12,0,100,0,0,38275,''),
(72228,0,0,'You do not have the strength to defeat him. You are too weak to carry on.',15,0,100,0,0,38786,''),
(72228,0,1,'Your allies think you are weak.',15,0,100,0,0,38785,''),
(72249,0,0,'Galakras staggers, but recovers from the blast!',41,0,100,0,0,0,''),
(72249,1,0,'Galakras is hit! Nice shot!',41,0,100,0,0,0,''),
(72302,0,0,'The Dragonmaw are supporting the Warchief.',12,0,100,1,0,38097,''),
(72302,1,0,'We\'re going to need some serious firepower.',12,0,100,1,0,38098,''),
(72302,2,0,'Here they come!',14,0,100,1,0,38099,''),
(72302,3,0,'I\'ve conjured a Blizzard, lead them into it!',14,0,100,0,0,38100,''),
(72302,4,0,'She\'s turning her siege weapons on her own towers!',14,0,100,0,0,38085,''),
(72302,5,0,'One down, one to go!',14,0,100,0,0,38086,''),
(72302,6,0,'We\'ve done it!',12,0,100,0,0,38088,''),
(72302,7,0,'We\'ll hold the docks for the remaining landing parties. Follow the path to the gates of Orgrimmar, and make contact with Vol\'jin and his revolutionaries.',12,0,100,0,0,38089,''),
(72311,0,0,'Well done! Landing parties, form up! Footmen to the front!',12,0,100,25,0,38953,''),
(72311,1,0,'Yes. My scouts learned all about this one."Warlord Zaela." Bring her proto-drake down and the rest of the Dragonmaw will crumble.',12,0,100,1,0,38954,''),
(72311,2,0,'Commandeer those towers! Turn the anti-air batteries around and blast her from the sky!',12,0,100,25,0,38955,''),
(72311,3,0,'Some of you will need to stay behind to hold the beachhead.',12,0,100,1,0,38170,''),
(72311,4,0,'That\'s both of them!  Fire the cannons!',14,0,100,22,0,38944,''),
(72311,5,0,'Ha!  The bigger they are...',12,0,100,153,0,38946,''),
(72311,6,0,'We will see if he has managed to keep up his end of the bargain.',12,0,100,1,0,38947,''),
(72432,0,0,'The Warchief ignored my council. I discovered he was building a compound beneath the caverns of Ragefire.',12,0,100,0,0,38564,''),
(72432,1,0,'Thrall and Saurfang have already gone down below.',12,0,100,0,0,38565,''),
(72432,2,0,'Go with caution.  Hellscream has been assembling an arsenal down there - goblin mercenaries, pandaren artifacts, and some sort of darkness I can feel in my very soul.',12,0,100,0,0,38567,''),
(72438,0,0,'Now is my chance!',12,0,100,0,0,0,''),
(72438,1,0,'Oh no, Ji! They are going to execute him!',12,0,100,0,0,38556,''),
(72438,2,0,'They have practically beaten him unconscious! I have to do something!',12,0,100,0,0,38557,''),
(72438,3,0,'Ji, I am so sorry, we can be together now, please, let us just go back to the turtle, please do not die.',12,0,100,0,0,38560,''),
(72438,4,0,'I am getting him out of here.',12,0,100,0,0,38561,''),
(72455,0,0,'Have anything to say for yourself, Pandaren?',14,0,100,1,0,39051,''),
(72455,1,0,'Do you see this burning candle? You have until it burns out to tell us about the Pandaren artifacts! Now start talking!',14,0,100,397,0,39052,''),
(72492,0,0,'We didn\'t want to do this!',12,0,100,5,0,39044,''),
(72492,1,0,'I owe you my life!',12,0,100,1,0,39045,''),
(72498,0,0,'I\'m so sorry!',12,0,100,18,0,38569,''),
(72560,0,0,'Well done. The first brigade has made landfall.',12,0,100,1,0,38167,''),
(72560,1,0,'Strategy, Dark Lady. We should repurpose the shore defenses.',12,0,100,1,0,38168,''),
(72560,2,0,'Heroes, take the towers, turn the guns onto that proto-drake, and blast it from the sky!',12,0,100,5,0,38169,''),
(72560,3,0,'Some of you should stay behind to hold the landing zone.',12,0,100,1,0,38956,''),
(72560,4,0,'She seems to be assaulting her own towers!',14,0,100,5,0,38152,''),
(72560,5,0,'We are halfway there!',14,0,100,5,0,38153,''),
(72560,6,0,'Sometimes I impress even myself. And down goes the dragon!',14,0,100,6,0,38154,''),
(72560,7,0,'Finally!  I will never get all of this dust out of my robes.',14,0,100,5,0,38155,''),
(72560,8,0,'I will take that as a compliment.  We\'ll hold the docks for now and marshall the forces. Vol\'jin should await you at the gates of Orgrimmar.',14,0,100,1,0,38156,''),
(72561,0,0,'I see the Dragonmaw have thrown in their lot with Garrosh.',12,0,100,1,0,38301,''),
(72561,1,0,'My arrows alone cannot bring that monstrosity down.',12,0,100,1,0,38302,''),
(72561,2,0,'Bring her down quick so I can wrap my fingers around her neck.',14,0,100,1,0,38303,''),
(72561,3,0,'And there goes the other one.',14,0,100,0,0,38293,''),
(72561,4,0,'You do realize we are directly below it, right?',14,0,100,0,0,38294,''),
(72561,5,0,'Oh, you\'re still here?  I had kind of hoped that you had perished.  You would make a very attractive corpse.',14,0,100,0,0,38295,''),
(72561,6,0,'If he\'s not dead.',14,0,100,0,0,38296,''),
(72779,0,0,'*Cough cough* Nyyyunnngggg...',12,0,100,0,0,38307,''),
(72779,1,0,'Cho... the outsiders... THEY did this... we should never have let them in...',12,0,100,0,0,38308,''),
(72964,0,0,'You\'re Screwed!',14,0,100,0,0,0,''),
(73316,0,0,'Welcome, $n. I\'ve had the market area cleared to make room for Halfhill\'s first noodle stand, run by you!',12,0,100,3,0,0,''),
(73316,1,0,'Customers will line up and wait for you to tell them to sit down. They will only wait for a short while before leaving so be sure to get them to a seat before they leave.',12,0,100,0,0,0,''),
(73316,2,0,'Click on a patron who is waiting in line. You should see them wave to you when you have successfully interacted with them.',12,0,100,0,0,0,''),
(73316,3,0,'When a customer has been selected, click on an open seat and the customer will go sit there.',12,0,100,0,0,0,''),
(73316,4,0,'Once seated, a customer will wait a short while for you to deliver their noodle soup. As with waiting in line, be sure to get the customer their food before they decide to leave.',12,0,100,0,0,0,''),
(73316,5,0,'Make some noodle soup for your customer. This is a scholar so they like the simplicity of a standard noodle soup. Try making one now.',12,0,100,0,0,0,''),
(73316,6,0,'Now that the soup is made, pick it up by clicking on it. Soups will go bad if left out too long so only make what you need for your customers.',12,0,100,0,0,0,''),
(73316,7,0,'Excellent! Now your customer will happily eat the noodle soup you\'ve made for them. When they\'re done they\'ll leave happy.',12,0,100,4,0,0,''),
(73316,8,0,'Some tips: You can always tell what a customer wants by their outfit.',12,0,100,0,0,0,''),
(73316,9,0,'Some customers are hungry, they\'ll want a second bowl after they finish their first.',12,0,100,0,0,0,''),
(73316,10,0,'Other customers are impatient, they won\'t wait as long; but are really happy when they are served quickly.',12,0,100,0,0,0,''),
(73316,11,0,'Now get out there and make some noodle soup!',12,0,100,0,0,0,''),
(73316,12,0,'Well done!',12,0,100,4,0,0,''),
(73330,0,0,'Ah, we adventure together again, except this time I am afraid that the circumstances are much more dire.',14,0,100,378,0,38120,''),
(73330,1,0,'The land is scarred, the ever-blooming trees and plants wither and die as the water from the pools drains away.',14,0,100,378,0,38122,''),
(73330,2,0,'Once, the Titans used these life-giving waters to create and shape all life in Pandaria.',14,0,100,0,0,38124,''),
(73330,3,0,'It is these waters that kept the Vale in bloom.  Their runoff into the Valley of the Four Winds created the most fertile farmland in the world!',14,0,100,378,0,38125,''),
(73330,4,0,'And now, the malignance of the Old God has manifested itself within the waters.',14,0,100,1,0,38126,''),
(73330,5,0,'Such a foul, foul thing - destroy it, before it seeps deep into the soil and corrupts all of Pandaria!',14,0,100,5,0,38127,''),
(73330,6,0,'Ah, you have done it!  The waters are pure once more.',14,0,100,5,0,38128,''),
(73330,7,0,'Can you feel their life-giving energies flow through you?',14,0,100,6,0,38129,''),
(73330,8,0,'It will take much time for the Vale to heal, but you have given us hope!',14,0,100,1,0,38130,''),
(73330,9,0,'Can it be...? Oh no, no no no no no.',14,0,100,274,0,38131,''),
(73330,10,0,'The Golden Lotus... they pledged their lives to defend this place.',14,0,100,1,0,38132,''),
(73330,11,0,'Yes!  Rook Stonetoe!  You remember me!  What has happened to you?',14,0,100,5,0,38133,''),
(73330,12,0,'I see. This sha energy has trapped their spirits here, to endlessly relive their failure. It feeds on their despair.',14,0,100,1,0,38134,''),
(73330,13,0,'This is a fate far worse than death - please, heroes!  Set their souls free!',14,0,100,1,0,38135,''),
(73330,14,0,'Be at peace, dear friends.',14,0,100,1,0,38136,''),
(73330,15,0,'May your souls become one with the land you gave your life to protect.',14,0,100,1,0,38137,''),
(73342,0,0,'Defend me!',14,0,100,0,0,0,''),
(73349,0,0,'Our work is not yet complete! Stop them!',14,0,100,0,0,0,''),
(73483,0,0,'It is not too late, Garrosh. Lay down the mantle of Warchief. We can end this here, now, with no more bloodshed.',14,0,100,0,0,38934,''),
(73483,1,0,'Then you have forced my hand.  I will correct the mistake I made long ago.  Spirits of the wind, the earth, the water, hear my call!  Come to my aid!',14,0,100,0,0,38935,''),
(73483,2,0,'Never powerless Garrosh. And never alone.',14,0,100,0,0,38936,''),
(73598,0,0,'So Hellscream\'s arrogance unleashed the last of the sha. I am not surprised.',12,0,100,0,0,38090,''),
(73598,1,0,'Gorehowl.',12,0,100,0,0,38091,''),
(73598,2,0,'News to no one, Regent Lord. King Wrynn\'s fleet is converging on Orgrimmar as we speak.',12,0,100,0,0,38092,''),
(73598,3,0,'I\'m warning you, Lor\'themar. The Alliance is besieging the city and we will destroy Hellscream. Your people had best stay out of our way.',12,0,100,0,0,38093,''),
(73598,4,0,'Come heroes, through the portal! The siege of Orgrimmar begins!',12,0,100,0,0,38094,''),
(73605,0,0,'Look here! He left his weapon behind.',14,0,100,0,0,38158,''),
(73605,1,0,'This means he\'s completely unhinged.',12,0,100,0,0,38159,''),
(73605,2,0,'Likewise. Sylvanas and I have both sent ships to support Vol\'jin\'s revolution.',12,0,100,0,0,38160,''),
(73605,3,0,'It is always a pleasure to see you, Lady Proudmoore.',12,0,100,0,0,38161,''),
(73716,0,0,'Ah, more of Vol\'jin\'s revolutionaries. You\'ve made it.',12,0,100,0,0,38920,'');
INSERT INTO `tmp_548_creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(73716,1,0,'Have you found Thrall? I am badly hurt, he insisted on going ahead alone.',12,0,100,0,0,38921,''),
(73716,2,0,'Tell me, how goes the battle up above? What of Nazgrim? Speak to me!',12,0,100,0,0,38922,''),
(73716,3,0,'Ah, Nazgrim. A great leader and a fine warrior. He valued his oath to the Warchief more than his life.',12,0,100,0,0,38923,''),
(73716,4,0,'I tried to tell him... to tell him that Hellscream betrayed us, cast aside a Warchief\'s responsibility to his own people.  But Nazgrim... too loyal... too proud.',12,0,100,0,0,38924,''),
(73716,5,0,'Damn Hellscream.  His ambition tore our Horde apart.',12,0,100,274,0,38925,''),
(73716,6,0,'Go on, find Thrall.  Finish this.  I will live.',12,0,100,1,0,38926,''),
(73859,0,0,'Send in da reserves! Charge!',14,0,100,0,0,0,''),
(73909,0,0,'I\'m summoning a Flamestrike, lead them into it!',14,0,100,0,0,0,''),
(73939,0,0,'Don\'t be foolish, Vol\'jin! You have no siege weapons left! You cannot win this battle!',14,0,100,5,0,38205,''),
(73939,1,0,'You may have defeated my war machine, but the gate still stands. You will not take Orgrimmar today.',14,0,100,274,0,38206,''),
(73939,2,0,'What? Kor\'kron, to the gates! Now!',14,0,100,397,0,38207,''),
(73941,0,0,'Our casualties are too heavy!',14,0,100,5,0,38262,''),
(73941,1,0,'Perhaps our newfound reinforcements will aid us.',12,0,100,1,0,38263,''),
(73941,2,0,'Perhaps there is hope after all.',12,0,100,1,0,38264,''),
(73941,3,0,'Blessings of the Earth Mother upon you.',14,1,100,0,0,0,''),
(73942,0,0,'Ain\'t no other way, mon. We gotta stop Garrosh here an\' now, else we be runnin\' the rest of our lives.',12,0,100,1,0,39151,''),
(73942,1,0,'Dey be heroes, no doubt about dat.',14,0,100,1,0,39144,''),
(73942,2,0,'Da beast be slain!',14,0,100,5,0,39145,''),
(73942,3,0,'Tyrande...',12,0,100,1,0,39153,''),
(73962,0,0,'Anu\'dora!',14,0,100,5,0,38309,''),
(73962,1,0,'At them, my sisters! For Kalimdor!',14,0,100,5,0,38310,''),
(73962,2,0,'Don\'t think we\'re here to save you, troll. We\'re here for Kalimdor.  Get forces inside the gates while we distract the enemy!',14,0,100,1,0,38311,''),
(74158,0,0,'Heh, sounds like Malkorok just tore apart those intruders.',12,0,100,0,0,0,''),
(74158,1,0,'I don\'t know, I\'ve got a bad feeling. It\'s way too quiet in there.',12,0,100,0,0,0,'');
INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) SELECT n.* FROM `tmp_548_creature_text` n WHERE n.`entry` NOT IN (SELECT `entry` FROM (SELECT DISTINCT `entry` FROM `creature_text`) AS s);
